<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesListRef;

trait PlatformIdentityRolesAttributeHolder
{
    protected PlatformIdentityRolesVO|PlatformIdentityRolesListRef| array |null $roles = null;
    protected bool $rolesAssigned = false;

    public function getRolesOrDefault(?PlatformIdentityRolesVO $roles): ?PlatformIdentityRolesVO
    {
        if ($this->rolesAssigned && $roles) {
            return PlatformIdentityRolesVO::from($this->roles)->getWithDefaults($roles);
        } elseif ($this->rolesAssigned) {
            return PlatformIdentityRolesVO::from($this->roles);
        } else {
            return $roles;
        }
    }
    public function roles(PlatformIdentityRolesVO|PlatformIdentityRolesListRef| array |null $roles): static
    {
        $this->roles = $roles;
        $this->rolesAssigned = true;
        return $this;
    }
    public function getRoles(): ?PlatformIdentityRolesListRef
    {
        return is_a($this->roles, PlatformIdentityRolesVO::class) ? $this->roles->value() : $this->roles;
    }
    public function unsetRoles(): static
    {
        $this->roles = null;
        $this->rolesAssigned = false;
        return $this;
    }
    protected function withDefaultRoles(): void
    {
    }
    protected function withAssertedRolesRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->rolesAssigned = $this->rolesAssigned) {
            $value->roles = PlatformIdentityRolesVO::tryFrom($this->roles, $errorsList);
        }
    }
}
